async function validatePdf(bytes){try{const data=bytes instanceof Uint8Array?bytes.slice():new Uint8Array(bytes);const p=await pdfjsLib.getDocument({data}).promise;await p.getPage(1);return true}catch(e){console.warn('Output validation failed',e);throw Error('The processed PDF could not be validated. No download was created. Please try another setting or file.') }}
async function renderPage(pdf,n,scale=.35){const p=await pdf.getPage(n),vp=p.getViewport({scale}),c=document.createElement('canvas');c.width=Math.max(1,Math.ceil(vp.width));c.height=Math.max(1,Math.ceil(vp.height));await p.render({canvasContext:c.getContext('2d',{alpha:false}),viewport:vp}).promise;return c}
function clearPreview(msg='Process the tool to preview the result here.'){const box=$('processedPreview');if(box)box.innerHTML=`<div class="empty">${esc(msg)}</div>`;if($('previewNav'))$('previewNav').hidden=true;if($('resultPreview'))$('resultPreview').hidden=true}
async function previewPdfBlob(blob){
 const token=++previewToken,box=$('processedPreview'),oldScroll=box?.scrollTop||0;
 let pdf;try{pdf=await pdfjsLib.getDocument({data:await blob.arrayBuffer()}).promise}catch(e){if(box)box.innerHTML='<div class="empty">Preview unavailable for this protected/encrypted output. Download and reopen it to verify.</div>';return}
 if(token!==previewToken||!box)return;
 const next=document.createElement('div');next.className='processed-preview-inner';
 const frag=document.createDocumentFragment();
 for(let i=1;i<=pdf.numPages;i++){const card=document.createElement('div');card.className='processed-page-card';card.dataset.page=i;card.innerHTML=`<div class="processed-page-slot"><span>Page ${i}</span></div><small>Page ${i}</small>`;frag.appendChild(card)}
 next.appendChild(frag);
 const first=next.querySelector('.processed-page-card');
 if(first){try{const c=await renderPage(pdf,1,.42);if(token!==previewToken)return;const slot=first.querySelector('.processed-page-slot');slot.innerHTML='';slot.appendChild(c)}catch(_){}}
 if(token!==previewToken)return;
 box.replaceChildren(...next.childNodes);box.scrollTop=Math.min(oldScroll,box.scrollHeight);
 $('previewNav').hidden=pdf.numPages<2;
 const io=new IntersectionObserver(async entries=>{for(const e of entries){if(!e.isIntersecting)continue;io.unobserve(e.target);if(token!==previewToken)return;const pn=Number(e.target.dataset.page);if(pn===1)return;const slot=e.target.querySelector('.processed-page-slot');try{const c=await renderPage(pdf,pn,.42);if(token!==previewToken)return;slot.innerHTML='';slot.appendChild(c)}catch(_){slot.textContent='Preview unavailable'}}},{root:box,rootMargin:'350px'});
 box.querySelectorAll('.processed-page-card').forEach(x=>io.observe(x));
}

async function setArtifact(data,name,type='application/pdf',preview='pdf',meta=''){let blob=data instanceof Blob?data:new Blob([data],{type});artifact={blob,name,type};const panel=$('resultPreview'),box=$('processedPreview');if(panel)panel.hidden=false;$('downloadBtn').hidden=false;$('downloadBtn').textContent=`⬇ Download ${name}`;$('downloadMeta').textContent=meta||fmtSize(blob.size);if(preview==='pdf')await previewPdfBlob(blob);else if(preview==='source-pdf'){if(primary){await previewPdfBlob(primary)}else if(box){box.innerHTML='<div class="empty">Output is ready. Use the download button below.</div>'}}else if(preview==='image'){const url=URL.createObjectURL(blob);box.innerHTML=`<div class="processed-single-image"><img src="${url}" alt="Processed preview"></div>`;setTimeout(()=>URL.revokeObjectURL(url),60000)}else if(preview==='none'){if(box)box.innerHTML='<div class="empty">Output is ready. Use the download button below.</div>';if($('previewNav'))$('previewNav').hidden=true;}}
$('downloadBtn').onclick=()=>{if(!artifact)return;const url=URL.createObjectURL(artifact.blob),a=document.createElement('a');a.href=url;a.download=artifact.name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),3000)};
