 if(kind==='rotate'){cards.addEventListener('click',e=>{const b=e.target.closest('[data-r]');if(!b)return;const card=b.closest('.page-card'),i=Number(card.dataset.page),delta=Number(b.dataset.r);pageRotations[i]=((pageRotations[i]||0)+delta)%360;const val=(pageRotations[i]+360)%360;card.querySelector('.thumb-slot').style.transform=`rotate(${val}deg)`;card.querySelector('.rotation-readout').textContent=`${val}°`;queueLivePreview()})}
