function updateReorderState(cards){reorderOrder=[...cards.querySelectorAll('.page-card')].map(c=>Number(c.dataset.original));[...cards.querySelectorAll('.page-card')].forEach((c,i)=>{c.dataset.page=i;c.querySelector('.page-label').textContent=`${i+1}. Original page ${Number(c.dataset.original)+1}`})}
function enableReorder(cards){cards.addEventListener('click',e=>{const b=e.target.closest('[data-move]');if(!b)return;const card=b.closest('.page-card'),dir=Number(b.dataset.move),sib=dir<0?card.previousElementSibling:card.nextElementSibling;if(!sib)return;if(dir<0)cards.insertBefore(card,sib);else cards.insertBefore(sib,card);updateReorderState(cards);queueLivePreview()});let drag=null;cards.addEventListener('pointerdown',e=>{const h=e.target.closest('.drag-handle');if(!h)return;const card=h.closest('.page-card');drag={card,pointerId:e.pointerId};h.setPointerCapture?.(e.pointerId);card.classList.add('dragging');e.preventDefault()});cards.addEventListener('pointermove',e=>{if(!drag)return;const under=document.elementFromPoint(e.clientX,e.clientY)?.closest('.page-card');if(!under||under===drag.card||under.parentElement!==cards)return;const r=under.getBoundingClientRect();cards.insertBefore(drag.card,e.clientY<r.top+r.height/2?under:under.nextElementSibling);updateReorderState(cards)});const end=()=>{if(!drag)return;drag.card.classList.remove('dragging');drag=null;updateReorderState(cards);queueLivePreview()};cards.addEventListener('pointerup',end);cards.addEventListener('pointercancel',end)}
function bindRotateShortcuts(){if(!$('rotateAllLeft'))return;const apply=delta=>{document.querySelectorAll('#pageCards .page-card').forEach(card=>{const i=Number(card.dataset.page);pageRotations[i]=delta===0?0:((pageRotations[i]||0)+delta)%360;const val=(pageRotations[i]+360)%360;card.querySelector('.thumb-slot').style.transform=`rotate(${val}deg)`;card.querySelector('.rotation-readout').textContent=`${val}°`});queueLivePreview()};$('rotateAllLeft').onclick=()=>apply(-90);$('rotateAllRight').onclick=()=>apply(90);$('rotateReset').onclick=()=>apply(0)}
