function setUploadProgress(pct,label='Loading file…'){const wrap=$('uploadProgress'),bar=$('uploadProgressBar'),txt=$('uploadProgressPct');if(!wrap)return;wrap.hidden=false;if(bar)bar.style.width=`${clamp(Math.round(pct),0,100)}%`;if(txt)txt.textContent=`${clamp(Math.round(pct),0,100)}%`;const b=wrap.querySelector('b');if(b)b.textContent=label}
