async function onFilesChosen(list,append=false){const incoming=[...list];if(!incoming.length)return;artifact=null;if($('downloadBtn'))$('downloadBtn').hidden=true;clearPreview();setUploadProgress(0,incoming.length>1?'Loading files…':'Loading file…');try{for(let i=0;i<incoming.length;i++)await warmFile(incoming[i],i,incoming.length)}catch(e){hideUploadProgress();setResult(e.message||'Could not read the selected file.',true);return}files=append?[...files,...incoming]:incoming;primary=files[0]||null;hideUploadProgress();refreshSelectedFiles();if(!primary)return;$('uploadName').textContent=files.length>1?`${files.length} files selected`:primary.name;setResult('File loaded. Preparing workspace…');if(id==='pdf-merge'){fileOrder=append?[...fileOrder,...incoming]:[...files];renderOrderList('file');setResult(`${files.length} PDFs ready. Drag to reorder, remove any file, then process.`);return}if(id==='images-to-pdf'){imageOrder=append?[...imageOrder,...incoming]:[...files];renderOrderList('image');setResult(`${files.length} image(s) ready. Drag to reorder, remove any image, then create the PDF.`);return}if(id==='pdf-compress')updateCompressionEstimate();if(id==='pdf-unlock'){await detectUnlock(primary);return}let pdf;try{pdf=await loadPdfJs();lastPdfJs=pdf}catch(e){setResult(e?.name==='PasswordException'?'This PDF is password protected. Use Unlock PDF with the correct password.':(e.message||'Could not read this PDF.'),true);return}updateAutoPageFields(pdf.numPages);if(needsPicker())await buildPagePicker(pdf);if(id==='pdf-metadata')setResult('PDF loaded. Click Read Metadata.');else if(id==='pdf-margin')updateMarginDimension(pdf);else setResult(`${pdf.numPages} page(s) loaded. Set options, then process.`)}
