 if(!window.DMOWordEngine?.convert)throw Error('Word compatibility engine did not load. Refresh and try again.');
 const language=$('ocrLanguage')?.value||'eng';
 const out=await window.DMOWordEngine.convert(primary,{language,onProgress:p=>{if(p?.message)setResult(`<b>${esc(p.message)}</b>${p.percent!=null?`<div class="ocr-inline-progress"><i style="width:${clamp(Number(p.percent)||0,0,100)}%"></i></div>`:''}`)}});
